    "objectiveId": "kum-09",
    "itemNumber": 9,
    "subject": "Kumar · fișă beta",
    "recto": "De ce transportul segmentar explică tubulopatiile?",
    "verso": "Fiecare segment are transportori și funcții specifice; disfuncția lor produce tipare de pierderi și tulburări electrolitice.",
    "sourceVersionId": "md-3f041fa4728831d0ed3ea1db12e7724028c01006bc0df2657909af1ba28a47ea",
