    "objectiveId": "kum-09",
    "itemNumber": 9,
    "subject": "Kumar · fișă beta",
    "recto": "Cum crește ADH permeabilitatea la apă a colectorului?",
    "verso": "Prin receptorul V2 și semnalizarea intracelulară care determină inserția aquaporinei 2 în membrana apicală.",
    "sourceVersionId": "md-3f041fa4728831d0ed3ea1db12e7724028c01006bc0df2657909af1ba28a47ea",
